#include <stdio.h>

int main(void) {
    unsigned int r, g, b;
    if (scanf("%u %u %u", &r, &g, &b) != 3) return 1;
    unsigned int mau = (r << 16) | (g << 8) | b;
    printf("0x%08X\n", mau);
    return 0;
}
